import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d as T,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"HTTP/3","description":"","frontmatter":{"title":"HTTP/3","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http3.md","filePath":"cs/http3.md","lastUpdated":1789023840000}'),C={name:"cs/http3.md"};function c(d,a,P,H,_,m){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="http-3" tabindex="-1">HTTP/3 <a class="header-anchor" href="#http-3" aria-label="Permalink to &quot;HTTP/3&quot;">​</a></h1><div class="epigraph"><p>把 HTTP 语义映到 QUIC 流：每请求一流，头用 QPACK；运输是 UDP 上的加密多流，不再套 TLS-over-TCP。</p><footer>—— 据 RFC 9114 HTTP/3；RFC 9204 QPACK 整理</footer></div><p><a href="/cs/hol-blocking">队头对照</a> 指向 QUIC。<a href="/cs/quic-streams-0rtt">QUIC 流</a> 已备运输。主干语义仍是 <a href="/cs/http-semantics">RFC 9110</a>。缺口是 <strong>HTTP/3 映射</strong>：SETTINGS、QPACK、Alt-Svc 发现。本课不把 Cookie 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTP/2 帧不能原样放进 QUIC：流模型与头压缩依赖 TCP 有序。H3：请求体走 QUIC 流，控制流另开，QPACK 用独立流传表更新以免头压缩再引入 HOL。发现：DNS HTTPS RR 或 Alt-Svc 从 H1/H2 升级。0-RTT 可早发 GET，须幂等。</p><p>不要把 H3 写成新方法新状态码。</p><p><span class="marginnote">RFC 9114。中间盒对 UDP 443 的态度决定能否用上上一课的迁移。</span></p><h3 id="语义不变运输换" tabindex="-1">语义不变运输换 <a class="header-anchor" href="#语义不变运输换" aria-label="Permalink to &quot;语义不变运输换&quot;">​</a></h3><p>QPACK 避免头压缩再 HOL。发现靠 Alt-Svc 或 HTTPS RR。UDP 不通则 H2。CDN 要终止 QUIC。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：H1 文本 / H2 二进制 TCP / H3 二进制 QUIC。画：浏览器 → QUIC 连接 → 多请求流。与 TSO：UDP GSO。</p>',11)),(e(),n(h,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEM%5B%22RFC%209110%20%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20H3%5B%22%E6%98%A0%E5%88%B0%20QUIC%20%E6%B5%81%22%5D%0A%20%20H3%20--%3E%20QP%5B%22QPACK%20%E6%97%A0%20HOL%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20DISC%5B%22Alt-Svc%2FHTTPS%20RR%22%5D%20--%3E%20H3%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连接迁移让移动 HTTP 会话活过 IP 变。BBR 常为默认 CC。MSS 变成 QUIC 包大小与 PMTUD。Cookie 仍是语义头，下一课。CDN 边缘要终止 QUIC，证书与 CID 路由是运营。</p><p>回退：UDP 不通则 H2。不是协议失败，是路径政策。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 WebTransport 的全部。Cookie 与会话是下一课。后课默认：H3 = HTTP 语义 + QUIC 运输。</p><p>公司只开 TCP 443 时用户看不见 H3 好处。</p><p>上一课留下的缺口在本课收口；「HTTP/3」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/cookies-sessions">Cookie 与会话</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语义不变，运输换 QUIC。</li><li>QPACK 避免头压缩 HOL。</li><li>发现与 UDP 路径是部署条件。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9114；RFC 9204。</li></ul>',10))])}const u=i(C,[["render",c]]);export{A as __pageData,u as default};
